/**
 * Hono-style TypeScript surface for the native `Server` NAPI class.
 *
 * `src/main.ts` re-exports the NAPI loader, whose `.d.ts` is generated by
 * NAPI-RS. That generator cannot describe JS callbacks or generic classes, so
 * every handler argument, `Context`, and the `fetch()` / `request()` results are
 * emitted as `unknown`. This module closes that gap at the TS layer, using the
 * same facade pattern as `request.ts` / `response.ts`: the exported value is the
 * *unmodified* native constructor, so `instanceof`, route registration and the
 * Rocket listener behave exactly as before.
 *
 * Every signature below mirrors `src/server.rs` (context object built at
 * 1068-1225, helpers at 1228-1401) rather than the Hono docs. In particular the
 * runtime `register()` (server.rs:737-768) accepts at most three arguments, so
 * route methods are declared with that ceiling instead of a variadic
 * `...middleware` that would silently drop extra handlers.
 *
 * Known remaining gap: true variadic middleware and `Server<E>` instance-method
 * generic propagation require extending `register()` in Rust; not claimed here.
 */
import * as native from "../dist/index.js";

type WebResponse = globalThis.Response;
type WebRequest = globalThis.Request;
type WebRequestInit = globalThis.RequestInit;

/** Bindings and variables made available to handlers (Hono `Server<E>` shape). */
export interface Env {
  Bindings?: object;
  Variables?: object;
}

type BindingsOf<E extends Env> = E extends { Bindings: infer B } ? B : Record<string, unknown>;
type VariablesOf<E extends Env> = E extends { Variables: infer V } ? V : Record<string, unknown>;

/** `c.req` — built at server.rs:1068-1092. No-arg `param`/`query`/`header` return all entries. */
export interface ContextRequest {
  readonly method: string;
  readonly url: string;
  readonly path: string;
  readonly raw: WebRequest;
  param(): Record<string, string>;
  param(name: string): string | undefined;
  query(): Record<string, string>;
  query(name: string): string | undefined;
  header(): Record<string, string>;
  header(name: string): string | undefined;
  text(): Promise<string>;
  json<T = unknown>(): Promise<T>;
  arrayBuffer(): Promise<ArrayBuffer>;
  blob(): Promise<Blob>;
  formData(): Promise<FormData>;
}

/** `c` — built at server.rs:1093-1225. `status`/`header` return `c` for chaining. */
export interface Context<E extends Env = Env> {
  readonly req: ContextRequest;
  readonly env: BindingsOf<E>;
  readonly executionCtx: unknown;
  readonly finalized: boolean;
  text(body: string, status?: number): WebResponse;
  json(value: unknown, status?: number): WebResponse;
  html(body: string, status?: number): WebResponse;
  body(data: string, status?: number, headers?: Record<string, string>): WebResponse;
  redirect(url: string, status?: number): WebResponse;
  status(code: number): Context<E>;
  header(name: string, value: string, options?: { append?: boolean }): Context<E>;
  set<K extends keyof VariablesOf<E>>(key: K, value: VariablesOf<E>[K]): void;
  get<K extends keyof VariablesOf<E>>(key: K): VariablesOf<E>[K] | undefined;
  notFound(): WebResponse;
  res(): WebResponse;
}

export type Next = () => Promise<void>;

/** A handler may return a Response (terminal) or nothing (middleware). */
export type Handler<E extends Env = Env> = (
  c: Context<E>,
  next: Next,
) => WebResponse | Promise<WebResponse> | void | Promise<void>;

export type NotFoundHandler<E extends Env = Env> = (
  c: Context<E>,
) => WebResponse | Promise<WebResponse>;

export type ErrorHandler<E extends Env = Env> = (
  error: unknown,
  c: Context<E>,
) => WebResponse | Promise<WebResponse>;

export type RouterInstance =
  | InstanceType<typeof native.RegExpRouter>
  | InstanceType<typeof native.TrieRouter>
  | InstanceType<typeof native.SmartRouter>;

/** `new Server(options)` — fields read at server.rs:241-298. */
export interface ServerOptions {
  strict?: boolean;
  port?: number;
  host?: string;
  router?: RouterInstance;
  getPath?: (request: WebRequest) => string;
  routes?: Record<string, unknown>;
  fetch?: (request: WebRequest) => WebResponse | Promise<WebResponse>;
}

/** At most three arguments, matching `register()` at server.rs:737-768. */
type RouteMethod<E extends Env> = {
  (path: string, handler: Handler<E>, extra?: Handler<E>): Server<E>;
  (handler: Handler<E>, extra?: Handler<E>, third?: Handler<E>): Server<E>;
};

export interface Server<E extends Env = Env> {
  readonly host: string;
  readonly port: number;
  readonly listening: boolean;
  get: RouteMethod<E>;
  post: RouteMethod<E>;
  put: RouteMethod<E>;
  delete: RouteMethod<E>;
  query: RouteMethod<E>;
  patch: RouteMethod<E>;
  options: RouteMethod<E>;
  head: RouteMethod<E>;
  all: RouteMethod<E>;
  on(
    method: string | string[],
    path: string | string[],
    handler: Handler<E>,
    extra?: Handler<E>,
  ): Server<E>;
  use(path: string, middleware: Handler<E>, extra?: Handler<E>): Server<E>;
  use(middleware: Handler<E>, extra?: Handler<E>): Server<E>;
  route(path: string, app: Server<E>): Server<E>;
  basePath(path: string): Server<E>;
  notFound(handler: NotFoundHandler<E>): Server<E>;
  onError(handler: ErrorHandler<E>): Server<E>;
  mount(path: string, application: Server<E>): Server<E>;
  fire(): void;
  fetch(request: WebRequest, bindings?: BindingsOf<E>, execution?: unknown): Promise<WebResponse>;
  request(
    input: string | WebRequest,
    init?: WebRequestInit,
    bindings?: BindingsOf<E>,
    execution?: unknown,
  ): Promise<WebResponse>;
  start(): Promise<number>;
  serve(): Promise<number>;
  stop(): Promise<void>;
}

/** Generic construct signature so `new Server<{ Bindings: B }>()` type-checks. */
export interface ServerConstructor {
  new <E extends Env = Env>(options?: ServerOptions): Server<E>;
}

export const Server: ServerConstructor = native.Server as unknown as ServerConstructor;
